const $=id=>document.getElementById(id),sheet=$('sheet'),content=$('sheet-content');
let state=null,busy=false,toastTimer,audio=null,soundNodes=[],lastSheet='';
function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
function btn(label,fn,cls='choice'){const b=el('button',label,cls);b.type='button';b.onclick=fn;return b;}
function prose(text){const e=el('div',undefined,'prose');for(const p of text.split('\n\n'))e.append(el('p',p));return e;}
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3800);}
function read(){try{const raw=localStorage.getItem(SAVE_KEY);return raw?hydrate(JSON.parse(raw)):null;}catch{return null;}}
function save(){if(!state)return;state.savedAt=new Date().toISOString();try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));$('save-status').textContent='Automatisch gespeichert · auf diesem Gerät';}catch{$('save-status').textContent='Speichern gesperrt · bitte über das Menü sichern';}}
function checkpoint(){try{localStorage.setItem(SAVE_KEY+'.checkpoint',JSON.stringify(state));}catch{}}
function update(){if(!state)return;$('location-name').textContent=AREAS[state.area].name;$('clock').textContent=time(state);$('clock-note').textContent=state.flags.late?'ROOK IST ABGEREIST':'ROOK GEHT UM 22:45';$('clock').parentElement.classList.toggle('late',!!state.flags.late);$('objective').textContent=objective(state);$('evidence-count').textContent=state.clues.length;$('deduction-dot').hidden=!Object.entries(DEDUCTIONS).some(([id,d])=>!state.deductions.includes(id)&&d.pair.every(k=>state.clues.includes(k)));$('watson').textContent=state.flags.rescued?'Watson im Foyer':'Watson';}
const world=new World($('world'),()=>state,id=>{save();if(id)showNode(id);},toast);
function open(label='',mode=''){sheet.className=mode;$('sheet-label').textContent=label;$('sheet-close').hidden=mode==='narrative';content.replaceChildren();if(!sheet.open)sheet.showModal();sheet.scrollTop=0;}
function closeSheet(){if(busy)return;sheet.close();lastSheet='';if(state){state.node=null;state.page=0;save();}}
$('sheet-close').onclick=closeSheet;sheet.addEventListener('cancel',e=>{if(sheet.classList.contains('narrative')||busy)e.preventDefault();else closeSheet();});
function enter(s){state=s;$('title-screen').hidden=true;$('game').hidden=false;world.sync();update();save();if(state.ending)showNode('epilogue',state.page);else if(state.node)showNode(state.node,state.page);}
function showNode(id,page=0){if(!state)return;if(id?.startsWith('@')){special(id);return;}if(state.ending&&id!=='epilogue'){showNode('epilogue');return;}state.node=id;const n=getNode(state,id);state.page=Math.min(Math.max(0,page),n.pages.length-1);open(n.speaker,'narrative');if(id==='epilogue'&&state.page===0){content.append(el('div','✦','ending-ornament'),el('h2',END_TITLES[state.ending],'ending-title'));}content.append(prose(n.pages[state.page]));if(n.pages.length>1){const paging=el('div',undefined,'reading-navigation');paging.setAttribute('aria-label','Textseiten');const previous=btn('Zurück',()=>showNode(id,state.page-1),'reading-back');previous.disabled=state.page===0;previous.setAttribute('aria-label','Vorherige Textseite');const count=el('span',`Seite ${state.page+1} von ${n.pages.length}`,'reading-position');count.setAttribute('aria-live','polite');paging.append(previous,count);content.append(paging);}const choices=el('div',undefined,'choices');if(state.page<n.pages.length-1)choices.append(btn('Weiter',()=>showNode(id,state.page+1),'primary'));else for(const c of n.choices){const b=btn(c.label,()=>take(c));b.disabled=!!c.disabled;if(c.test)b.append(el('small',`${SKILLS[c.test.skill].name} · W20 + ${SKILLS[c.test.skill].bonus} · Ziel ${c.test.dc}`));else if(c.cost)b.append(el('small',`${c.cost*5} Minuten`));choices.append(b);}content.append(choices);save();}
async function take(c){if(busy||c.disabled)return;if(c.next?.startsWith('@')){special(c.next);return;}busy=true;const oldArea=state.area,oldClues=state.clues.length,wasLate=state.flags.late;try{let r=null;if(c.test){sheet.close();r=await diceCheck(c.test);}const next=apply(state,c,r);if(oldArea!==state.area){world.sync();flash();}update();save();if(c.event==='rescue'||c.flags?.includes('arrival'))checkpoint();if(!wasLate&&state.flags.late)toast('22:45 · Rook ist abgereist. Die Beweise bleiben wichtig.');else if(state.clues.length>oldClues)toast('Ein neuer Beweis liegt in Ihrer Mappe.');if(next)showNode(next);else{sheet.close();state.node=null;save();}}catch(e){open('Ein Moment');content.append(el('p',e.message));content.append(btn('Zurück',()=>showNode(state.node||'watson')));}finally{busy=false;}}
function special(id){if(id==='@case')showCase();else if(id==='@export')exportSave();else if(id==='@title')title();else if(id.startsWith('@clue:'))showClue(id.split(':')[1]);}
function flash(){const e=$('travel-flash');e.classList.remove('active');void e.offsetWidth;e.classList.add('active');}
function diceCheck(spec){return new Promise(resolve=>{const modal=$('dice-dialog');$('dice-context').textContent=SKILLS[spec.skill].name;$('die').textContent='?';$('dice-math').textContent=`W20 + ${SKILLS[spec.skill].bonus} · Ziel ${spec.dc}`;$('dice-result').textContent='';$('dice-result').className='';$('roll').textContent='Würfel werfen';$('roll').disabled=false;modal.showModal();$('roll').onclick=async()=>{$('roll').disabled=true;const r=roll(spec.skill,spec.dc);$('die').classList.add('rolling');tone(240,.18);let count=0;const timer=setInterval(()=>{$('die').textContent=String((count++*7)%20+1);},60);await new Promise(r=>setTimeout(r,matchMedia('(prefers-reduced-motion: reduce)').matches?80:800));clearInterval(timer);$('die').classList.remove('rolling');$('die').textContent=r.value;$('dice-math').textContent=`${r.value} + ${r.bonus} = ${r.total}`;$('dice-result').textContent=r.success?'Gelungen':'Misslungen · es gibt einen anderen Weg';$('dice-result').className=r.success?'success':'error';tone(r.success?460:160,.25);$('roll').textContent='Weiter';$('roll').disabled=false;$('roll').onclick=()=>{modal.close();resolve(r);};};});}
$('dice-dialog').addEventListener('cancel',e=>e.preventDefault());
function showMap(){open('LONDON & DAS THEATER');content.append(el('h2','Welcher Spur folgen Sie?'),el('p','Ortswechsel kosten 5 Minuten. Lesen und Nachdenken kosten keine Zeit.','small'));const grid=el('div',undefined,'map-grid');for(const [id,a]of Object.entries(AREAS)){const unlocked=canTravel(state,id);const b=btn('',()=>goArea(id),'place-card'+(id===state.area?' current':''));b.disabled=!unlocked;const photo=el('span',undefined,'place-image');photo.style.backgroundImage=`url(assets/${a.atlas})`;photo.style.backgroundPosition=`${a.tile%2?100:0}% ${a.tile>1?100:0}%`;const text=el('span',unlocked?a.label:'Noch keine Spur', 'place-copy');text.append(el('small',id===state.area?'Hier sind Sie':unlocked?'5 Minuten':id==='trap'?'Claras Weg herleiten':id==='printer'?'Adresse finden':'Fahrkarte finden'));b.append(photo,text);grid.append(b);}content.append(grid);}
function goArea(id){try{const wasLate=state.flags.late,old=state.area;travel(state,id);sheet.close();world.sync();update();save();if(old!==id)flash();if(!wasLate&&state.flags.late)toast('22:45 · Rook ist abgereist.');if(id==='theatre'&&!state.flags.arrival)showNode('arrival');}catch(e){toast(e.message);}}
function showSpots(){open(AREAS[state.area].name);content.append(el('h2','Den Ort untersuchen'),el('p',AREAS[state.area].desc,'small'));const list=el('div',undefined,'choices');for(const sp of AREAS[state.area].spots)list.append(btn(sp[3],()=>{closeSheet();world.go(sp);}));content.append(list);}
function showEvidence(){open('BEWEISMAPPE');content.append(el('h2','Was Sie gesichert haben'));if(!state.clues.length){content.append(el('p','Noch keine Beweise. Erkunden Sie das Theater und sprechen Sie mit den Menschen.','empty'));return;}const list=el('div',undefined,'evidence-list');for(const id of state.clues){const c=CLUES[id],b=btn('',()=>showClue(id),'evidence-card');b.append(el('span',c.type==='Zeugenaussage'?'“':'⌕'),el('strong',c.name),el('small',c.source));list.append(b);}content.append(list);}
function showClue(id){if(!state.clues.includes(id)){toast('Diesen Beweis haben Sie noch nicht gefunden.');return;}const c=CLUES[id];open(c.type.toUpperCase());content.append(el('h2',c.name),el('p',c.source,'small'),el('div',c.detail,'document '+c.kind),prose(c.text));const choices=el('div',undefined,'choices');choices.append(btn('Mit anderen Beweisen verbinden',()=>showCase('deduce')),btn('Zur Beweismappe',showEvidence));content.append(choices);}
function caseTabs(tab){const tabs=el('div',undefined,'tool-tabs');for(const [id,label]of [['overview','Ermittlung'],['deduce','Kombinieren'],['journal','Notizen']])tabs.append(btn(label,()=>showCase(id),id===tab?'selected':''));return tabs;}
function showCase(tab='overview'){open('FALLAKTE 01');content.append(el('h2','Die letzte Vorstellung'),caseTabs(tab));if(tab==='overview'){content.append(el('p','Clara Vale wurde zuletzt um 20:55 in ihrer Garderobe gesehen. Um 21:05 war sie verschwunden. Victor Rook verlässt das Theater um 22:45.','notice'));for(const [id,d]of Object.entries(DEDUCTIONS)){const card=el('div',undefined,'deduction'+(state.deductions.includes(id)?' solved':''));card.append(el('h3',state.deductions.includes(id)?d.title:({route:'Wohin führte Claras Weg?',opportunity:'Wer hatte Zugang und Gelegenheit?',motive:'Was sollte Clara unterschreiben?'})[id]),el('p',state.deductions.includes(id)?d.explain:'Noch nicht belegt. Verbinden Sie unter „Kombinieren“ zwei passende Beweise.'));content.append(card);}content.append(el('p',state.flags.rescued?'Clara ist in Sicherheit.':'Claras Aufenthaltsort ist noch nicht gesichert.','notice'));if(state.ending)content.append(btn('Den Ausgang noch einmal lesen',()=>showNode('epilogue'),'primary'));else{content.append(btn('Watson um einen Denkanstoß bitten',()=>showNode('watson')));content.append(btn('Den Fall abschließen',showAccusation,'secondary full'));}}else if(tab==='deduce'){content.append(el('p','Was belegen zwei Ihrer Fundstücke gemeinsam? Die App prüft Ihre Verbindung, ohne Zeit verstreichen zu lassen.','small'));if(state.clues.length<2){content.append(el('p','Sichern Sie zunächst mindestens zwei Beweise.','empty'));return;}const selects=[];for(const title of ['Erster Beweis','Zweiter Beweis']){const label=el('label',undefined,'field');label.append(el('span',title));const select=el('select');select.append(new Option('Beweis auswählen',''));for(const id of state.clues)select.append(new Option(CLUES[id].name,id));label.append(select);content.append(label);selects.push(select);}const label=el('label',undefined,'field');label.append(el('span','Meine Schlussfolgerung'));const theory=el('select');theory.append(new Option('Schlussfolgerung auswählen',''));for(const [id,d]of Object.entries(DEDUCTIONS))theory.append(new Option(d.title,id));label.append(theory);content.append(label);const feedback=el('p','','notice');feedback.hidden=true;feedback.setAttribute('role','status');const b=btn('Verbindung prüfen',()=>{if(!theory.value){feedback.hidden=false;feedback.textContent='Wählen Sie eine Schlussfolgerung.';return;}const r=deduce(state,selects[0].value,selects[1].value,theory.value);feedback.hidden=false;feedback.textContent=r.text;feedback.className='notice '+(r.ok?'success':'');if(r.ok){tone(450,.2);update();save();}feedback.scrollIntoView({block:'nearest'});},'primary');b.disabled=!!state.ending;content.append(b,feedback);}else{if(!state.journal.length)content.append(el('p','Ihre Notizen entstehen während der Ermittlung.','empty'));for(const entry of state.journal){const row=el('div',undefined,'journal-entry');row.append(el('small',entry.time),el('p',entry.text));content.append(row);}if(state.rolls.length){content.append(el('h3','Würfelproben'));for(const r of state.rolls)content.append(el('p',r,'small'));}}}
function showAccusation(){open('IHRE SCHLUSSFOLGERUNG');content.append(el('h2','Was berichten Sie Lestrade?'),el('p','Dies beendet den Fall. Eine richtige Beschuldigung braucht Belege für Zugang und Gelegenheit sowie für das Motiv. Sie können vorher weiter ermitteln.','notice'));const suspects=el('div',undefined,'suspects');for(const [id,name,description]of [['rook','Victor Rook','Verwalter des Theaters'],['beaumont','Arthur Beaumont','Direktor des Theaters'],['mercer','Eli Mercer','Bühnenmeister'],['none','Noch niemanden beschuldigen','Den bisherigen Stand an Scotland Yard übergeben']]){const b=btn(name,()=>confirmAccusation(id,name),'suspect');b.append(el('span',description));suspects.append(b);}content.append(suspects,btn('Weiter ermitteln',closeSheet));}
function confirmAccusation(id,name){open('FALL ABSCHLIESSEN');content.append(el('h2',id==='none'?'Die Ermittlung abgeben?':name+' beschuldigen?'),el('p','Ihre Entscheidung wird als Ausgang dieses Falls gespeichert. Wenn Sie später einen anderen Weg versuchen möchten, können Sie zum letzten Kapitelanfang zurückkehren.','notice'),btn('Entscheidung bestätigen',()=>{finish(state,id);update();save();showNode('epilogue');},'primary'),btn('Noch einmal überlegen',showAccusation));}
function exportSave(){if(!state){const loaded=read();if(loaded)state=loaded;else return;}save();const data={...state,continuity:continuity(state)};const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=el('a');a.href=u;a.download='holmes-fall-01-spielstand.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function title(){if(state)save();sheet.close();world.active=false;$('game').hidden=true;$('title-screen').hidden=false;refreshTitle();}
function refreshTitle(){const has=!!read();$('continue').hidden=!has;$('begin').textContent=has?'Den Fall neu beginnen':'Die Akte öffnen';}
function begin(){const s=fresh();enter(s);checkpoint();}
$('begin').onclick=()=>{if(read()){open('NEUE ERMITTLUNG');content.append(el('h2','Den Fall von vorn beginnen?'),el('p','Der bisherige Spielstand wird beim Start ersetzt. Sie können ihn vorher als Datei sichern.','notice'),btn('Bisherigen Spielstand sichern',exportSave),btn('Eine neue Ermittlung beginnen',begin,'primary'),btn('Abbrechen',closeSheet));}else begin();};
$('continue').onclick=()=>{const s=read();if(s)enter(s);};
function importDialog(){open('SPIELSTAND LADEN');content.append(el('h2','Eine gesicherte Akte öffnen'),el('p','Die gewählte Datei ersetzt Ihren aktuellen Spielstand. Sichern Sie ihn vorher, wenn Sie ihn behalten möchten.','notice'));if(read())content.append(btn('Aktuellen Stand sichern',exportSave));content.append(btn('Datei auswählen',()=>$('import').click(),'primary'));}
$('import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>250000)throw Error('Diese Datei ist zu groß.');const s=hydrate(JSON.parse(await file.text()));sheet.close();enter(s);checkpoint();}catch(err){open('NICHT GELADEN');content.append(el('p',err.message));}e.target.value='';};
function restartCheckpoint(){let raw;try{raw=localStorage.getItem(SAVE_KEY+'.checkpoint');if(!raw)throw Error();hydrate(JSON.parse(raw));}catch{toast('Noch kein Kapitelanfang gesichert.');return;}open('EINEN ANDEREN WEG VERSUCHEN');content.append(el('h2','Zum Kapitelanfang zurückkehren?'),el('p','Beweise, Zeit und Entscheidungen seit diesem Punkt werden zurückgesetzt. Ihr aktuelles Ergebnis können Sie vorher exportieren.','notice'),btn('Aktuelles Ergebnis sichern',exportSave),btn('Zum gesicherten Anfang zurück',()=>{const s=hydrate(JSON.parse(raw));s.ending=null;delete s.flags.ending;s.node=s.flags.rescued?null:s.flags.arrival?null:'intro';s.page=0;sheet.close();enter(s);},'primary'),btn('Abbrechen',closeSheet));}
function menu(){open('HOLMES & WATSON');content.append(el('h2','Eine kurze Pause'));const choices=el('div',undefined,'choices');if(state||read())choices.append(btn('Spielstand sichern',exportSave));choices.append(btn('Spielstand laden',importDialog));if(state)choices.append(btn('Zum Kapitelanfang zurück',restartCheckpoint));choices.append(btn('Steuerung & Würfel',help),btn('Bild & Klang',settings));if(state)choices.append(btn('Zur Fallauswahl',title));else choices.append(btn('Schließen',closeSheet));content.append(choices);}
function help(){open('STEUERUNG & WÜRFEL');content.append(el('h2','Die Ermittlung liegt bei Ihnen'),prose('Tippen Sie auf einen freien Weg, um Holmes zu bewegen. Die leuchtenden Markierungen führen zu Personen und Gegenständen. Über „Erkunden“ erreichen Sie dieselben Punkte als Liste.\n\nIn „Orte“ wählen Sie ein anderes Ziel. Neue Adressen erschließen sich durch Hinweise. Jede Reise kostet fünf Minuten; aufwendige Handlungen zeigen ihre Dauer vorab. Lesen und Kombinieren kosten keine Zeit. Rook reist um 22:45 ab.\n\nBei riskanten Handlungen: W20 + Fähigkeitsbonus. Erreicht die Summe das angezeigte Ziel, gelingt der Versuch. Misslingen kostet manchmal Zeit oder verschließt diesen einen Weg. Ein alternativer Zugang bleibt möglich.\n\nIn der Fallakte verbinden Sie zwei Beweise mit einer Schlussfolgerung. Die endgültige Beschuldigung würfeln Sie nicht aus. Watson gibt nur auf Ihre Bitte Denkanstöße.\n\nDie Handlung ist ein eigener fiktionaler Fall. Weitere Fälle können Ihr gespeichertes Ergebnis übernehmen; sie sind noch nicht Teil dieser App.'));}
function settings(){open('BILD & KLANG');content.append(el('h2','Atmosphäre'),el('p','Klang ist zunächst ausgeschaltet. Die Einstellung Ihres Geräts für reduzierte Bewegung wird respektiert.','small'),btn(audio&&audio.state==='running'?'Klang umschalten':'Atmosphärischen Klang einschalten',toggleSound),el('p','Grafiken: eigens erzeugte Illustrationen. Die Spielstände liegen nur in diesem Browser; jede Person spielt unabhängig.','notice'));}
function tone(f,d){if(!state?.sound||!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=f;g.gain.setValueAtTime(.025,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+d);}
async function toggleSound(){try{if(!state)state=read()||fresh();if(!audio)audio=new (window.AudioContext||window.webkitAudioContext)();await audio.resume();state.sound=!state.sound;for(const n of soundNodes){try{n.stop();}catch{}}soundNodes=[];if(state.sound){const length=audio.sampleRate*3,buffer=audio.createBuffer(1,length,audio.sampleRate),arr=buffer.getChannelData(0);let prev=0;for(let i=0;i<length;i++){prev=(prev+(Math.random()*2-1)*.025)/1.025;arr[i]=prev;}const noise=audio.createBufferSource(),gain=audio.createGain(),filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=900;gain.gain.value=.1;noise.buffer=buffer;noise.loop=true;noise.connect(filter);filter.connect(gain);gain.connect(audio.destination);noise.start();soundNodes.push(noise);}$('sound').setAttribute('aria-pressed',String(state.sound));$('sound').setAttribute('aria-label',state.sound?'Klang ausschalten':'Klang einschalten');save();toast(state.sound?'Leiser Raumklang eingeschaltet':'Klang ausgeschaltet');}catch{toast('Der Klang lässt sich gerade nicht starten.');}}
$('menu').onclick=menu;$('title-menu').onclick=menu;$('sound').onclick=toggleSound;$('map').onclick=showMap;$('spots').onclick=showSpots;$('case').onclick=()=>showCase();$('evidence').onclick=showEvidence;$('watson').onclick=()=>{if(state.flags.rescued&&state.area!=='theatre'){open('DR. WATSON');content.append(prose('Watson versorgt Clara im Theater. Wenn Sie ihn sprechen möchten, finden Sie ihn dort.'),btn('Zum Theater fahren',()=>goArea('theatre')),btn('Weiter ermitteln',closeSheet));}else showNode('watson');};
window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.hidden){save();audio?.suspend();}else if(state?.sound)audio?.resume();});window.addEventListener('keydown',e=>{if(!state||!world.active||document.querySelector('dialog[open]'))return;const moves={ArrowUp:[0,-.06],ArrowDown:[0,.06],ArrowLeft:[-.05,0],ArrowRight:[.05,0],w:[0,-.06],s:[0,.06],a:[-.05,0],d:[.05,0]};if(moves[e.key]){e.preventDefault();const [x,y]=moves[e.key];world.go([null,world.hero.x+x,world.hero.y+y]);}});
refreshTitle();
