if(document.modelContext?.registerTool){const life=new AbortController();const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:life.signal})).catch(()=>{});}catch{}};register({name:'read_investigation',description:'Read the current location, clock, found evidence and established deductions. No hidden solution.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){return state?{location:AREAS[state.area].name,time:time(state),clues:state.clues.map(k=>({id:k,name:CLUES[k].name})),deductions:state.deductions,ending:state.ending}:{started:false};}});register({name:'open_found_evidence',description:'Open one already discovered clue in the evidence viewer. Does not discover new evidence.',inputSchema:{type:'object',properties:{clueId:{type:'string'}},required:['clueId'],additionalProperties:false},execute(input){if(!input||typeof input.clueId!=='string'||!state?.clues.includes(input.clueId))throw Error('Only a found clue may be opened.');showClue(input.clueId);return {opened:input.clueId};}});window.addEventListener('pagehide',()=>life.abort(),{once:true});}
